type Versioned<T> = {
    version: number;
    value: T;
};
/**
 * Highest published version and its contents. Falls back to older versions if
 * the newest is pruned between listing and reading, and to `empty` when none
 * exist yet.
 *
 * `validate` makes the read fail CLOSED, and any caller whose state is a safety
 * invariant should pass one. Without it the only check is the root's
 * object-vs-array shape: `T` is erased at runtime, so a file that merely parses
 * is trusted and a plausible-looking record with wrong field types reaches the
 * mutator as if it were real state. A claim whose `expiry` is a string compares
 * false against every clock — so a live claim reads as absent and the replay it
 * exists to reject is granted.
 *
 * With a validator, a version that is readable but does not match is FATAL
 * rather than skipped. Skipping would be the same fail-open one level down: an
 * older version is by definition missing every record published since, so
 * falling back to one forgets state exactly the way `empty()` does. Only an
 * UNREADABLE file is still skipped, because that is the benign pruning race —
 * and pruning never removes the newest version.
 */
export declare function readVersioned<T>(base: string, empty: () => T, validate?: (value: unknown) => boolean): Promise<Versioned<T>>;
/**
 * Read the current state, apply `mutate`, and publish the result — retrying
 * from a fresh read whenever another writer wins the race to publish.
 *
 * `mutate` may throw to reject the change (a cap being exceeded, say); it runs
 * against freshly-read state on every attempt, so a rejection is never based
 * on a total some other process has already moved past.
 *
 * `validate` is passed through to `readVersioned` — see the note there on why
 * a store holding safety state wants one.
 */
export declare function updateVersioned<T, R>(base: string, empty: () => T, mutate: (value: T) => R | Promise<R>, validate?: (value: unknown) => boolean): Promise<R>;
export {};
